using System.Reflection;using System.Runtime.CompilerServices;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Effects;using DeskCanvas.Core;
namespace DeskCanvas.App.Windows;
internal static class V30RuntimePolish{[ModuleInitializer]internal static void Init(){EventManager.RegisterClassHandler(typeof(Border),FrameworkElement.LoadedEvent,new RoutedEventHandler(Loaded));EventManager.RegisterClassHandler(typeof(MainWindow),FrameworkElement.LoadedEvent,new RoutedEventHandler(MainLoaded));}private static void Loaded(object s,RoutedEventArgs e){if(s is not Border b)return;if(b.Effect is DropShadowEffect&&IsStandardCard(b))b.Effect=null;if(IsSystem(b))FitSystem(b);}private static bool IsStandardCard(Border b)=>b.Child is Panel p&&p.Descendants().OfType<TextBlock>().Any(t=>t.Text is "SYSTEM STATUS" or "再生中"||t.FontSize>=45);private static bool IsSystem(Border b)=>b.Child is Panel p&&p.Descendants().OfType<TextBlock>().Any(t=>t.Text=="SYSTEM STATUS");private static void FitSystem(Border b){b.SizeChanged+=(_,__)=>{if(b.Child is not UIElement c)return;var sx=Math.Clamp(b.ActualWidth/300d,.42,1.6);var sy=Math.Clamp(b.ActualHeight/210d,.42,1.6);c.RenderTransformOrigin=new Point(.5,0);c.RenderTransform=new ScaleTransform(sx,sy);};}private static void MainLoaded(object s,RoutedEventArgs e){if(s is MainWindow w)w.AddLayerButtons();}
}
internal static class VisualTreeExt{internal static IEnumerable<DependencyObject> Descendants(this DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var c=VisualTreeHelper.GetChild(root,i);yield return c;foreach(var d in c.Descendants())yield return d;}}}
partial class MainWindow{private void AddLayerButtons(){if(EditorPanel.Children.OfType<WrapPanel>().Any(p=>Equals(p.Tag,"v30-layer")))return;var panel=new WrapPanel{Tag="v30-layer",Margin=new Thickness(0,10,0,0)};foreach(var pair in new[]{("最前面",2), ("上へ",1), ("下へ",-1), ("最背面",-2)}){var button=new Button{Content=pair.Item1,ToolTip=pair.Item1};button.Click+=(_,__)=>MoveLayer(pair.Item2);panel.Children.Add(button);}EditorPanel.Children.Add(panel);}private void MoveLayer(int step){if(SelectedItem is not { } item)return;var type=controller.GetType();var items=controller.Items.OrderBy(x=>x.ZIndex).ToList();var index=items.IndexOf(item);if(step==2){type.GetMethod("BringToFront",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,[item]);return;}if(step==-2){type.GetMethod("SendToBack",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,[item]);return;}var target=Math.Clamp(index+step,0,items.Count-1);if(target==index)return;(items[index].ZIndex,items[target].ZIndex)=(items[target].ZIndex,items[index].ZIndex);type.GetMethod("NormalizeZOrder",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,null);}}
